private fun Collection<DopeQuery>.toQueryStringWithBrackets(quantifier: AggregateQuantifier?) =
    map { it.queryString }.formatStringListToQueryStringWithBrackets(
        prefix = quantifier?.let { "${it.queryString} " }.orEmpty(),
    )

private fun Collection<String>.formatStringListToQueryStringWithBrackets(prefix: String = "") =
    joinToString(separator = ", ", prefix = "($prefix", postfix = ")")
